pub fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }

    // Capacity is exactly 2n - 1; compute with checked arithmetic to avoid overflow.
    let cap = n
        .checked_mul(2)
        .and_then(|x| x.checked_sub(1))
        .expect("input slice too large to intersperse safely");

    let mut res = Vec::with_capacity(cap);

    for (i, &x) in numbers.iter().enumerate() {
        if i != 0 {
            res.push(delim);
        }
        res.push(x);
    }

    res
}

